:root {
  --ink: #07050b;
  --panel: rgba(14, 9, 20, .93);
  --line: rgba(190, 150, 200, .22);
  --pale: #eadfe6;
  --muted: #a294a8;
  --rose: #c85578;
  --rose-bright: #ff7d9d;
  --gold: #e6bd7a;
  --violet: #7a5a92;
  --serif: "Palatino Linotype", "Book Antiqua", Palatino, Georgia, serif;
  --mono: "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;
  --safe-l: env(safe-area-inset-left, 0px);
  --safe-r: env(safe-area-inset-right, 0px);
  --safe-b: env(safe-area-inset-bottom, 0px);
  --safe-t: env(safe-area-inset-top, 0px);
}

* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }

html, body {
  margin: 0;
  height: 100%;
  overflow: hidden;
  background: #050308;
  color: var(--pale);
  font-family: var(--serif);
  overscroll-behavior: none;
}

body {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  touch-action: none;
  -webkit-user-select: none;
  user-select: none;
}

#app { position: fixed; inset: 0; overflow: hidden; }

#stage {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background:
    radial-gradient(ellipse at 50% 42%, rgba(50, 20, 60, .34), transparent 62%),
    radial-gradient(ellipse at 50% 120%, rgba(120, 22, 52, .16), transparent 55%),
    #050308;
}

#game {
  display: block;
  width: min(100vw, calc(100vh * 16 / 9));
  height: auto;
  aspect-ratio: 16 / 9;
  image-rendering: pixelated;
  image-rendering: crisp-edges;
  background: #08060d;
  box-shadow: 0 0 0 1px rgba(190, 150, 200, .08), 0 30px 90px rgba(0, 0, 0, .75);
}

#scanlines {
  position: absolute;
  width: min(100vw, calc(100vh * 16 / 9));
  aspect-ratio: 16 / 9;
  pointer-events: none;
  opacity: .16;
  background: repeating-linear-gradient(to bottom, rgba(255,255,255,.06) 0 1px, transparent 1px 3px);
  mix-blend-mode: overlay;
}

/* ---------- title & panels ---------- */
.screen {
  position: absolute;
  inset: 0;
  display: none;
  align-items: center;
  justify-content: center;
  padding: calc(18px + var(--safe-t)) calc(18px + var(--safe-r)) calc(18px + var(--safe-b)) calc(18px + var(--safe-l));
  z-index: 30;
}
.screen.active { display: flex; }

#title {
  background:
    radial-gradient(ellipse at 50% 38%, rgba(40, 14, 52, .18), rgba(4, 2, 7, .72) 72%),
    linear-gradient(180deg, rgba(4,2,7,.5), rgba(4,2,7,.86));
  text-align: center;
}

.title-inner {
  display: flex;
  flex-direction: column;
  align-items: center;
  max-width: 700px;
  animation: rise 1.2s cubic-bezier(.2,.8,.2,1) both;
}

@keyframes rise {
  from { opacity: 0; transform: translateY(14px); }
  to { opacity: 1; transform: none; }
}

.eyebrow {
  font-family: var(--mono);
  font-size: clamp(7px, 1.15vw, 11px);
  letter-spacing: .34em;
  color: #b9a1b6;
  text-transform: uppercase;
  margin-bottom: clamp(10px, 2.2vh, 20px);
  opacity: .8;
}

h1 {
  margin: 0;
  font-family: var(--serif);
  font-weight: 400;
  font-size: clamp(38px, 8.6vw, 92px);
  line-height: .88;
  letter-spacing: .1em;
  text-indent: .1em;
  color: #f1e5ea;
  text-shadow:
    0 0 18px rgba(255, 110, 150, .22),
    0 0 60px rgba(160, 40, 90, .28),
    0 3px 0 #2b1320,
    0 5px 22px #000;
}
h1 span {
  font-style: italic;
  color: #e7b4c4;
  letter-spacing: .14em;
}

.title-rule {
  display: flex;
  align-items: center;
  gap: 14px;
  width: min(310px, 64vw);
  margin: clamp(10px, 2vh, 18px) 0 clamp(8px, 1.5vh, 12px);
  color: var(--rose);
  font-size: 11px;
}
.title-rule i { flex: 1; height: 1px; background: linear-gradient(90deg, transparent, rgba(200, 85, 120, .65), transparent); }
.title-rule b { font-weight: 400; text-shadow: 0 0 10px rgba(255, 100, 140, .7); }

.sub {
  margin: 0 0 clamp(16px, 3.2vh, 28px);
  font-style: italic;
  font-size: clamp(12px, 1.8vw, 17px);
  color: #bda9b8;
  letter-spacing: .04em;
}

.menu {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 9px;
  width: min(260px, 70vw);
}

.btn {
  appearance: none;
  position: relative;
  border: 1px solid rgba(190, 150, 200, .26);
  background: linear-gradient(180deg, rgba(32, 20, 42, .72), rgba(13, 8, 19, .82));
  color: #d8cbd5;
  font-family: var(--mono);
  font-size: clamp(10px, 1.3vw, 12px);
  letter-spacing: .22em;
  text-transform: uppercase;
  padding: 13px 18px;
  cursor: pointer;
  transition: border-color .18s, color .18s, background .18s, transform .12s;
  clip-path: polygon(8px 0, 100% 0, 100% calc(100% - 8px), calc(100% - 8px) 100%, 0 100%, 0 8px);
}
.btn:hover, .btn:focus-visible {
  border-color: rgba(230, 130, 160, .6);
  color: #fff;
  background: linear-gradient(180deg, rgba(62, 26, 50, .8), rgba(20, 9, 24, .9));
  outline: none;
}
.btn:active { transform: translateY(1px); }
.btn.primary {
  border-color: rgba(220, 110, 145, .48);
  color: #f3dbe2;
  background: linear-gradient(180deg, rgba(92, 30, 55, .8), rgba(34, 12, 26, .9));
  box-shadow: inset 0 0 18px rgba(255, 90, 130, .1), 0 0 24px rgba(160, 40, 80, .14);
}
.btn.primary:hover { background: linear-gradient(180deg, rgba(126, 38, 68, .9), rgba(48, 15, 33, .95)); }
.btn.danger { color: #b98b98; }
.btn[hidden] { display: none; }

.hint {
  margin-top: clamp(14px, 2.6vh, 24px);
  font-family: var(--mono);
  font-size: clamp(7.5px, 1vw, 10px);
  letter-spacing: .14em;
  color: #7e6e83;
  line-height: 1.7;
  max-width: 520px;
}

.title-footer {
  position: absolute;
  bottom: calc(10px + var(--safe-b));
  left: 0;
  right: 0;
  text-align: center;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: .26em;
  color: #584a5e;
}

/* ---------- panel screens ---------- */
.panel-screen {
  background:
    radial-gradient(ellipse at 50% 45%, rgba(48, 16, 58, .55), rgba(4, 2, 7, .9) 70%);
  backdrop-filter: blur(2px);
  z-index: 40;
}
.panel {
  width: min(420px, 88vw);
  border: 1px solid var(--line);
  background:
    linear-gradient(180deg, rgba(24, 14, 32, .96), rgba(9, 5, 13, .97));
  padding: clamp(20px, 4vw, 34px);
  text-align: center;
  box-shadow: 0 0 0 1px rgba(0,0,0,.6), 0 30px 100px rgba(0,0,0,.8), inset 0 0 60px rgba(110, 40, 90, .08);
  clip-path: polygon(14px 0, 100% 0, 100% calc(100% - 14px), calc(100% - 14px) 100%, 0 100%, 0 14px);
  animation: rise .35s ease both;
}
.panel.wide { width: min(640px, 92vw); }
.panel-mark { color: var(--rose); font-size: 20px; margin-bottom: 6px; text-shadow: 0 0 16px rgba(255,90,130,.65); }
.panel-mark.blood { color: #9c2745; }
.panel-mark.gold { color: var(--gold); text-shadow: 0 0 18px rgba(255,200,110,.7); }
.panel h2 {
  margin: 0 0 6px;
  font-weight: 400;
  font-size: clamp(24px, 4.6vw, 38px);
  letter-spacing: .06em;
  color: #f0e2e8;
}
.panel-sub {
  margin: 0 0 20px;
  color: #9d8b9f;
  font-style: italic;
  font-size: clamp(11px, 1.5vw, 14px);
  line-height: 1.6;
}
.panel .menu { width: min(240px, 100%); margin: 0 auto; }
.panel .btn { padding: 11px 16px; }

/* map */
#map-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  grid-template-rows: repeat(3, auto);
  gap: 6px;
  margin: 12px 0 16px;
}
.map-cell {
  position: relative;
  min-height: clamp(46px, 9vw, 66px);
  border: 1px solid rgba(150, 120, 160, .16);
  background: rgba(255,255,255,.015);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  padding: 5px;
  cursor: default;
  transition: .2s;
}
.map-cell.known {
  border-color: rgba(200, 140, 170, .34);
  background: linear-gradient(180deg, rgba(80, 30, 60, .26), rgba(24, 12, 30, .4));
}
.map-cell.current {
  border-color: rgba(255, 140, 170, .8);
  box-shadow: 0 0 18px rgba(200, 60, 100, .24), inset 0 0 14px rgba(200, 60, 100, .15);
}
.map-cell .glyph { font-size: 15px; color: #c9a4b8; line-height: 1; }
.map-cell.known .glyph { color: #f0b8ca; }
.map-cell .name {
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: .07em;
  color: #9b849d;
  text-align: center;
  line-height: 1.3;
  text-transform: uppercase;
}
.map-cell.current .name { color: #f4dce4; }
.map-cell .here {
  position: absolute;
  top: 3px; right: 4px;
  font-size: 7px;
  color: var(--rose-bright);
  animation: pulse 1.6s infinite;
}
@keyframes pulse { 0%,100% { opacity: 1 } 50% { opacity: .35 } }
.map-cell.empty { border-style: dashed; opacity: .35; }
.relic-row {
  display: flex;
  justify-content: center;
  gap: 12px;
  min-height: 34px;
  margin-bottom: 4px;
}
.relic {
  width: 30px; height: 30px;
  display: flex; align-items: center; justify-content: center;
  border: 1px solid rgba(190, 150, 200, .2);
  color: #5b4c61;
  font-size: 15px;
}
.relic.owned {
  color: #f2c3d2;
  border-color: rgba(230, 140, 170, .55);
  box-shadow: 0 0 14px rgba(200, 70, 110, .25), inset 0 0 10px rgba(200, 70, 110, .15);
}
.relic span { font-family: var(--mono); font-size: 7px; letter-spacing: .08em; margin-left: 5px; }

/* victory */
.victory-stats {
  display: flex;
  justify-content: center;
  gap: clamp(12px, 4vw, 34px);
  margin: 4px 0 22px;
}
.victory-stats div { display: flex; flex-direction: column; gap: 4px; }
.victory-stats b { font-weight: 400; font-size: clamp(18px, 3vw, 26px); color: var(--gold); }
.victory-stats span { font-family: var(--mono); font-size: 7.5px; letter-spacing: .16em; color: #8e7c93; text-transform: uppercase; }

/* ---------- HUD icon buttons ---------- */
#hud-buttons {
  position: absolute;
  top: calc(8px + var(--safe-t));
  right: calc(8px + var(--safe-r));
  display: none;
  gap: 6px;
  z-index: 25;
}
body.playing #hud-buttons { display: flex; }
.icon-btn {
  width: 34px; height: 34px;
  display: flex; align-items: center; justify-content: center;
  border: 1px solid rgba(190, 150, 200, .22);
  background: rgba(10, 6, 15, .62);
  color: #b9a4bb;
  cursor: pointer;
  padding: 0;
  backdrop-filter: blur(3px);
}
.icon-btn svg { width: 18px; height: 18px; }
.icon-btn:hover { color: #fff; border-color: rgba(230, 140, 170, .6); }
.icon-btn:active { transform: translateY(1px); }

/* ---------- touch controls ---------- */
#touch-ui { position: absolute; inset: 0; display: none; z-index: 20; pointer-events: none; }
body.touch #touch-ui { display: block; }

#stick-zone {
  position: absolute;
  left: 0;
  bottom: 0;
  width: 48%;
  height: 56%;
  pointer-events: auto;
  touch-action: none;
}
#stick-base {
  position: absolute;
  left: calc(24px + var(--safe-l));
  bottom: calc(26px + var(--safe-b));
  width: clamp(86px, 17vw, 126px);
  height: clamp(86px, 17vw, 126px);
  border-radius: 50%;
  border: 1px solid rgba(210, 170, 220, .2);
  background: radial-gradient(circle, rgba(60, 30, 70, .18), rgba(10, 6, 15, .28) 72%);
  box-shadow: inset 0 0 24px rgba(160, 80, 140, .08);
  pointer-events: none;
  transform: translate(0, 0);
  transition: opacity .2s;
}
#stick-base::after {
  content: "";
  position: absolute;
  inset: 32%;
  border-radius: 50%;
  border: 1px dashed rgba(210, 170, 220, .12);
}
#stick-knob {
  position: absolute;
  left: 50%; top: 50%;
  width: 44%; height: 44%;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  border: 1px solid rgba(255, 170, 200, .34);
  background: radial-gradient(circle at 38% 32%, rgba(140, 70, 110, .55), rgba(40, 16, 44, .68));
  box-shadow: 0 0 18px rgba(200, 70, 120, .18);
}
#stick-base.dragging { border-color: rgba(255, 140, 170, .45); }

#action-buttons {
  position: absolute;
  right: calc(14px + var(--safe-r));
  bottom: calc(14px + var(--safe-b));
  width: clamp(190px, 40vw, 280px);
  height: clamp(170px, 40vw, 250px);
  pointer-events: none;
}
.action-btn {
  position: absolute;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  border: 1px solid rgba(220, 160, 190, .26);
  background: radial-gradient(circle at 36% 30%, rgba(92, 40, 74, .5), rgba(14, 8, 20, .72) 70%);
  color: rgba(245, 210, 225, .82);
  pointer-events: auto;
  touch-action: none;
  padding: 0;
  box-shadow: 0 0 22px rgba(0,0,0,.4), inset 0 0 18px rgba(255, 120, 160, .07);
  transition: transform .08s, background .08s, border-color .08s;
}
.action-btn svg { width: 46%; height: 46%; filter: drop-shadow(0 1px 2px rgba(0,0,0,.6)); }
.action-btn.pressed {
  transform: scale(.93);
  border-color: rgba(255, 160, 195, .75);
  background: radial-gradient(circle at 36% 30%, rgba(150, 55, 100, .72), rgba(30, 12, 36, .85) 70%);
  color: #fff;
}
.action-btn.jump { right: 0; bottom: 0; width: clamp(66px, 13vw, 88px); height: clamp(66px, 13vw, 88px); }
.action-btn.attack { right: clamp(62px, 12vw, 88px); bottom: clamp(52px, 10vw, 76px); width: clamp(62px, 12.5vw, 84px); height: clamp(62px, 12.5vw, 84px); }
.action-btn.dash { right: 0; bottom: clamp(82px, 16vw, 122px); width: clamp(52px, 10vw, 68px); height: clamp(52px, 10vw, 68px); opacity: .9; }

#rotate-hint {
  position: absolute;
  bottom: calc(6px + var(--safe-b));
  left: 50%;
  transform: translateX(-50%);
  z-index: 22;
  display: none;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: .16em;
  color: #6f5c76;
  white-space: nowrap;
  pointer-events: none;
}
@media (orientation: portrait) and (max-width: 700px) {
  #rotate-hint { display: block; }
  #stage { align-items: flex-start; padding-top: 12vh; }
  #hud-buttons { top: auto; bottom: calc(6px + var(--safe-b)); right: calc(8px + var(--safe-r)); }
  body.playing #hud-buttons { opacity: .75; }
}

/* desktop: hide touch UI even if touch capable */
@media (pointer: fine) and (min-width: 901px) {
  body.touch #touch-ui { display: none; }
}

@media (max-width: 900px) {
  #hud-buttons { display: none !important; }
}

#boot-error {
  position: absolute;
  inset: 20% 10%;
  z-index: 100;
  background: #14070c;
  border: 1px solid #7a2438;
  color: #ffc7d4;
  font-family: var(--mono);
  font-size: 12px;
  padding: 20px;
  white-space: pre-wrap;
  overflow: auto;
}

@media (max-height: 520px) {
  .title-inner { transform: scale(.82); }
  .hint { display: none; }
  .title-footer { display: none; }
  .panel { padding: 16px 22px; }
  .panel h2 { font-size: 22px; }
  .panel-sub { margin-bottom: 10px; }
  .panel .menu { flex-direction: row; flex-wrap: wrap; justify-content: center; }
  .panel .btn { flex: 1 1 40%; }
}

// Vesper's Lament — procedural gothic audio (WebAudio, no assets)
export class Sound {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.musicGain = null;
    this.sfxGain = null;
    this.muted = false;
    this.room = 'A';
    this.timer = null;
    this.padTimer = null;
    this.step = 0;
    this.playing = false;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.55;
    this.master.connect(this.ctx.destination);
    this.musicGain = this.ctx.createGain();
    this.musicGain.gain.value = 0.16;
    this.musicGain.connect(this.master);
    this.sfxGain = this.ctx.createGain();
    this.sfxGain.gain.value = 0.42;
    this.sfxGain.connect(this.master);
    this.noise = this.makeNoise();
  }

  makeNoise() {
    const len = this.ctx.sampleRate * 1.2;
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const d = buf.getChannelData(0);
    let last = 0;
    for (let i = 0; i < len; i++) {
      const white = Math.random() * 2 - 1;
      last = (last + 0.02 * white) / 1.02;
      d[i] = last * 3.2;
    }
    return buf;
  }

  setMuted(m) {
    this.muted = m;
    if (this.master) this.master.gain.setTargetAtTime(m ? 0 : 0.55, this.ctx.currentTime, 0.05);
  }

  toggleMute() {
    this.setMuted(!this.muted);
    return this.muted;
  }

  tone({ freq = 440, dur = 0.18, type = 'sine', vol = 0.2, slide = 0, attack = 0.005, dest = null, detune = 0 }) {
    if (!this.ctx || this.muted) return;
    const t = this.ctx.currentTime;
    const o = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    o.type = type;
    o.frequency.setValueAtTime(freq, t);
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(20, freq * slide), t + dur);
    o.detune.value = detune;
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, vol), t + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g);
    g.connect(dest || this.sfxGain);
    o.start(t);
    o.stop(t + dur + 0.05);
  }

  noiseBurst({ dur = 0.2, vol = 0.2, freq = 800, q = 1, type = 'bandpass', slide = 1, dest = null }) {
    if (!this.ctx || this.muted) return;
    const t = this.ctx.currentTime;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noise;
    const f = this.ctx.createBiquadFilter();
    f.type = type;
    f.frequency.setValueAtTime(freq, t);
    if (slide !== 1) f.frequency.exponentialRampToValueAtTime(Math.max(40, freq * slide), t + dur);
    f.Q.value = q;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(vol, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(f); f.connect(g); g.connect(dest || this.sfxGain);
    src.start(t);
    src.stop(t + dur + 0.02);
  }

  play(name) {
    if (!this.ctx || this.muted) return;
    switch (name) {
      case 'jump':
        this.tone({ freq: 240, dur: 0.16, type: 'square', vol: 0.09, slide: 2.1 });
        this.tone({ freq: 480, dur: 0.1, type: 'triangle', vol: 0.05, slide: 1.7 });
        break;
      case 'doublejump':
        this.tone({ freq: 420, dur: 0.18, type: 'triangle', vol: 0.1, slide: 2.4 });
        this.noiseBurst({ dur: 0.14, vol: 0.08, freq: 2400, q: 2 });
        break;
      case 'dash':
        this.noiseBurst({ dur: 0.28, vol: 0.16, freq: 1800, q: 1.2, slide: 0.22 });
        this.tone({ freq: 150, dur: 0.22, type: 'sawtooth', vol: 0.05, slide: 0.6 });
        break;
      case 'slash':
        this.noiseBurst({ dur: 0.16, vol: 0.16, freq: 3200, q: 0.9, slide: 0.18 });
        this.tone({ freq: 880, dur: 0.1, type: 'triangle', vol: 0.05, slide: 0.5 });
        break;
      case 'hit':
        this.noiseBurst({ dur: 0.16, vol: 0.22, freq: 500, q: 1.4, slide: 0.35 });
        this.tone({ freq: 130, dur: 0.14, type: 'square', vol: 0.08, slide: 0.55 });
        break;
      case 'playerhit':
        this.tone({ freq: 180, dur: 0.3, type: 'sawtooth', vol: 0.15, slide: 0.35 });
        this.noiseBurst({ dur: 0.3, vol: 0.2, freq: 700, q: 0.8, slide: 0.3 });
        break;
      case 'kill':
        this.noiseBurst({ dur: 0.32, vol: 0.15, freq: 900, q: 0.7, slide: 0.2 });
        this.tone({ freq: 320, dur: 0.28, type: 'triangle', vol: 0.07, slide: 0.5 });
        break;
      case 'ember':
        this.tone({ freq: 1180, dur: 0.12, type: 'sine', vol: 0.08, slide: 1.5 });
        this.tone({ freq: 1760, dur: 0.18, type: 'sine', vol: 0.045, slide: 1.25 });
        break;
      case 'heal':
        [523, 659, 784, 1046].forEach((f, i) => setTimeout(() => this.tone({ freq: f, dur: 0.5, type: 'sine', vol: 0.06 }), i * 90));
        break;
      case 'relic':
        [392, 523, 659, 784, 1046].forEach((f, i) => setTimeout(() => {
          this.tone({ freq: f, dur: 0.9, type: 'triangle', vol: 0.07 });
          this.tone({ freq: f * 2, dur: 0.7, type: 'sine', vol: 0.025 });
        }, i * 120));
        break;
      case 'gate':
        this.tone({ freq: 90, dur: 0.5, type: 'sawtooth', vol: 0.08, slide: 0.6 });
        this.noiseBurst({ dur: 0.4, vol: 0.1, freq: 400, q: 0.7 });
        break;
      case 'death':
        [330, 294, 247, 196, 147].forEach((f, i) => setTimeout(() => this.tone({ freq: f, dur: 0.9, type: 'triangle', vol: 0.08 }), i * 180));
        break;
      case 'bossintro':
        this.tone({ freq: 55, dur: 2.2, type: 'sawtooth', vol: 0.12, attack: 0.4 });
        this.tone({ freq: 82.4, dur: 2.4, type: 'triangle', vol: 0.07, attack: 0.6 });
        this.noiseBurst({ dur: 1.4, vol: 0.08, freq: 240, q: 0.6, slide: 0.5 });
        break;
      case 'bosshit':
        this.noiseBurst({ dur: 0.2, vol: 0.18, freq: 600, q: 1.2, slide: 0.4 });
        this.tone({ freq: 110, dur: 0.2, type: 'square', vol: 0.07, slide: 0.7 });
        break;
      case 'victory':
        [392, 523, 659, 784, 1046, 1318].forEach((f, i) => setTimeout(() => {
          this.tone({ freq: f, dur: 1.6, type: 'triangle', vol: 0.08 });
          this.tone({ freq: f / 2, dur: 1.4, type: 'sine', vol: 0.05 });
        }, i * 200));
        break;
      case 'ui':
        this.tone({ freq: 660, dur: 0.07, type: 'triangle', vol: 0.05 });
        break;
      case 'deny':
        this.tone({ freq: 120, dur: 0.16, type: 'square', vol: 0.06, slide: 0.8 });
        break;
    }
  }

  // ---- music ----
  startMusic(room) {
    if (!this.ctx) return;
    this.room = room;
    if (this.playing) return;
    this.playing = true;
    this.step = 0;
    this.tick = this.tick.bind(this);
    this.timer = setInterval(this.tick, 560);
    this.padTimer = setInterval(() => this.pad(), 7200);
    this.pad();
  }

  stopMusic() {
    this.playing = false;
    clearInterval(this.timer);
    clearInterval(this.padTimer);
    this.timer = null;
    this.padTimer = null;
  }

  setMood(room) {
    this.room = room;
  }

  get scale() {
    // A harmonic minor-ish, transposed by room mood
    if (this.room === 'G') return [110, 130.81, 164.81, 174.61, 220, 261.63, 329.63, 349.23];
    if (this.room === 'D') return [98, 116.54, 146.83, 155.56, 196, 233.08, 293.66, 311.13];
    if (this.room === 'E' || this.room === 'F') return [123.47, 146.83, 185, 196, 246.94, 293.66, 369.99, 392];
    return [110, 130.81, 164.81, 174.61, 220, 261.63, 329.63, 349.23];
  }

  tick() {
    if (!this.ctx || this.muted) return;
    const sc = this.scale;
    const s = this.step++;
    const pattern = [0, 2, 4, 2, 5, 4, 2, 1];
    if (s % 2 === 0) {
      const n = sc[pattern[(s / 2) % pattern.length] % sc.length];
      this.pluck(n, 1.9);
    }
    if (s % 4 === 3) {
      this.pluck(sc[3] * 2, 0.7, 0.35);
    }
  }

  pluck(freq, dur, vol = 0.5) {
    const t = this.ctx.currentTime;
    const o = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    const f = this.ctx.createBiquadFilter();
    o.type = 'triangle';
    o.frequency.value = freq;
    f.type = 'lowpass';
    f.frequency.setValueAtTime(2600, t);
    f.frequency.exponentialRampToValueAtTime(500, t + dur);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(0.05 * vol, t + 0.02);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(f); f.connect(g); g.connect(this.musicGain);
    o.start(t); o.stop(t + dur + 0.05);
  }

  pad() {
    if (!this.ctx || this.muted) return;
    const sc = this.scale;
    const root = sc[0] / 2;
    [1, 1.5, 2, 2.996].forEach((m, i) => {
      const t = this.ctx.currentTime;
      const o = this.ctx.createOscillator();
      const g = this.ctx.createGain();
      const f = this.ctx.createBiquadFilter();
      o.type = i === 3 ? 'sawtooth' : 'sine';
      o.frequency.value = root * m * (i === 3 ? 1.005 : 1);
      f.type = 'lowpass';
      f.frequency.value = 700;
      g.gain.setValueAtTime(0.0001, t);
      g.gain.linearRampToValueAtTime(0.012 / (i + 1), t + 1.6);
      g.gain.linearRampToValueAtTime(0.0001, t + 7.4);
      o.connect(f); f.connect(g); g.connect(this.musicGain);
      o.start(t); o.stop(t + 7.6);
    });
  }
}

// Room data and tilemap generation for Vesper's Lament
export const TILE = 16;
export const COLS = 30;
export const ROWS = 17;
export const VIEW_W = COLS * TILE;
export const VIEW_H = ROWS * TILE;

const WALL = '#';

function blankGrid() {
  const g = [];
  for (let y = 0; y < ROWS; y++) {
    g.push(new Array(COLS).fill('.'));
  }
  // outer shell
  for (let x = 0; x < COLS; x++) { g[0][x] = WALL; g[ROWS - 1][x] = WALL; }
  for (let y = 0; y < ROWS; y++) { g[y][0] = WALL; g[y][COLS - 1] = WALL; }
  // floor
  for (let x = 1; x < COLS - 1; x++) { g[15][x] = WALL; g[16][x] = WALL; }
  return g;
}

function applyOps(g, ops = []) {
  for (const op of ops) {
    const [kind, ...a] = op;
    if (kind === 'fill') {
      const [x, y, w, h, c = WALL] = a;
      for (let yy = y; yy < y + h; yy++) for (let xx = x; xx < x + w; xx++) {
        if (yy >= 0 && yy < ROWS && xx >= 0 && xx < COLS) g[yy][xx] = c;
      }
    } else if (kind === 'carve') {
      const [x, y, w, h] = a;
      for (let yy = y; yy < y + h; yy++) for (let xx = x; xx < x + w; xx++) {
        if (yy >= 0 && yy < ROWS && xx >= 0 && xx < COLS) g[yy][xx] = '.';
      }
    } else if (kind === 'ground') {
      const [x, w, row = 15] = a;
      for (let xx = x; xx < x + w; xx++) for (let yy = row; yy < ROWS; yy++) {
        if (xx >= 0 && xx < COLS) g[yy][xx] = WALL;
      }
    } else if (kind === 'platform') {
      const [x, y, w] = a;
      for (let xx = x; xx < x + w; xx++) {
        if (xx >= 0 && xx < COLS && y >= 0 && y < ROWS) g[y][xx] = '=';
      }
    } else if (kind === 'spikes') {
      const [x, y, w] = a;
      for (let xx = x; xx < x + w; xx++) {
        if (xx >= 0 && xx < COLS && y >= 0 && y < ROWS) g[y][xx] = '^';
      }
    } else if (kind === 'pillar') {
      const [x, y, h] = a;
      for (let yy = y; yy < y + h; yy++) {
        if (yy >= 0 && yy < ROWS) g[yy][x] = WALL;
      }
    }
  }
  return g;
}

function carveDoors(g, doors = []) {
  for (const d of doors) {
    if (d.side === 'left') for (const r of d.rows) g[r][0] = '.';
    if (d.side === 'right') for (const r of d.rows) g[r][COLS - 1] = '.';
    if (d.side === 'top') for (const c of d.cols) g[0][c] = '.';
    if (d.side === 'bottom') for (const c of d.cols) { g[ROWS - 1][c] = '.'; g[ROWS - 2][c] = '.'; }
  }
}

