      ctx.lineTo(110 + i * 160 - shift, 0);
      ctx.lineTo(190 + i * 160 - shift, 272);
      ctx.lineTo(80 + i * 160 - shift, 272);
      ctx.closePath(); ctx.fill();
    }
    ctx.globalAlpha = 1;
