    ctx.globalAlpha = .06;
    ctx.fillStyle = '#b7a6c9';
    ctx.beginPath(); ctx.ellipse(240 - shift, 238, 250, 20, 0, 0, Math.PI * 2); ctx.fill();
    ctx.globalAlpha = 1;
  } else if (room.theme === 'ossuary') {
