    // drips
    for (let i = 0; i < 6; i++) {
      const dx = 30 + i * 76;
      const dy = (t * .6 + i * 41) % 210;
      px(ctx, dx, 20 + dy, 1, 3, 'rgba(150,210,205,.25)');
    }
