    ctx.fillStyle = '#8fd8cf';
    ctx.beginPath(); ctx.ellipse(240, 120, 230, 120, 0, 0, Math.PI * 2); ctx.fill();
    ctx.globalAlpha = 1;
  } else if (room.theme === 'tower') {
    // huge window
