    ctx.save();
    pointedArch(ctx, 174 - shift * .5, 34, 134, 184); ctx.clip();
    const sky = ctx.createLinearGradient(0, 30, 0, 210);
    sky.addColorStop(0, '#161a35'); sky.addColorStop(.6, '#20223f'); sky.addColorStop(1, '#2b2438');
