    ctx.strokeStyle = '#2b2740'; ctx.lineWidth = 2;
    line(ctx, 240 - shift * .5, 34, 240 - shift * .5, 218, '#2b2740', 2);
    line(ctx, 176 - shift * .5, 150, 306 - shift * .5, 150, '#2b2740', 2);
    // beams / rafters
    for (let i = 0; i < 4; i++) {
