    ctx.beginPath();
    ctx.moveTo(76 - shift, 96);
    ctx.quadraticCurveTo(92 - shift, 86, 104 - shift, 96);
    ctx.lineTo(108 - shift, 132);
    ctx.quadraticCurveTo(90 - shift, 144, 72 - shift, 132);
    ctx.closePath(); ctx.fill();
    px(ctx, 88 - shift, 78, 4, 10, '#171222');
