    px(ctx, 0, 258, W, 14, '#15121e');
    px(ctx, 0, 258, W, 2, '#2c2739');
    for (let i = 0; i < 20; i++) px(ctx, i * 25 + 4, 264, 10, 8, '#0e0b15');
