179:     this.padTimer = setInterval(() => this.pad(), 7200);
180:     this.pad();
181:   }
182: 
183:   stopMusic() {
184:     this.playing = false;
185:     clearInterval(this.timer);
186:     clearInterval(this.padTimer);
187:     this.timer = null;
188:     this.padTimer = null;
189:   }
