191:   setMood(room) {
192:     this.room = room;
193:   }
194: 
195:   get scale() {
196:     // A harmonic minor-ish, transposed by room mood
197:     if (this.room === 'G') return [110, 130.81, 164.81, 174.61, 220, 261.63, 329.63, 349.23];
198:     if (this.room === 'D') return [98, 116.54, 146.83, 155.56, 196, 233.08, 293.66, 311.13];
199:     if (this.room === 'E' || this.room === 'F') return [123.47, 146.83, 185, 196, 246.94, 293.66, 369.99, 392];
200:     return [110, 130.81, 164.81, 174.61, 220, 261.63, 329.63, 349.23];
201:   }
202: 
203:   tick() {
204:     if (!this.ctx || this.muted) return;
205:     const sc = this.scale;
206:     const s = this.step++;
207:     const pattern = [0, 2, 4, 2, 5, 4, 2, 1];
208:     if (s % 2 === 0) {
209:       const n = sc[pattern[(s / 2) % pattern.length] % sc.length];
210:       this.pluck(n, 1.9);
211:     }
212:     if (s % 4 === 3) {
213:       this.pluck(sc[3] * 2, 0.7, 0.35);
214:     }
215:   }
216: 
217:   pluck(freq, dur, vol = 0.5) {
218:     const t = this.ctx.currentTime;
219:     const o = this.ctx.createOscillator();
220:     const g = this.ctx.createGain();
221:     const f = this.ctx.createBiquadFilter();
222:     o.type = 'triangle';
223:     o.frequency.value = freq;
224:     f.type = 'lowpass';
225:     f.frequency.setValueAtTime(2600, t);
226:     f.frequency.exponentialRampToValueAtTime(500, t + dur);
227:     g.gain.setValueAtTime(0.0001, t);
228:     g.gain.exponentialRampToValueAtTime(0.05 * vol, t + 0.02);
229:     g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
230:     o.connect(f); f.connect(g); g.connect(this.musicGain);
231:     o.start(t); o.stop(t + dur + 0.05);
232:   }
233: 
234:   pad() {
235:     if (!this.ctx || this.muted) return;
236:     const sc = this.scale;
237:     const root = sc[0] / 2;
238:     [1, 1.5, 2, 2.996].forEach((m, i) => {
239:       const t = this.ctx.currentTime;
240:       const o = this.ctx.createOscillator();
241:       const g = this.ctx.createGain();
242:       const f = this.ctx.createBiquadFilter();
243:       o.type = i === 3 ? 'sawtooth' : 'sine';
244:       o.frequency.value = root * m * (i === 3 ? 1.005 : 1);
245:       f.type = 'lowpass';
246:       f.frequency.value = 700;
247:       g.gain.setValueAtTime(0.0001, t);
248:       g.gain.linearRampToValueAtTime(0.012 / (i + 1), t + 1.6);
249:       g.gain.linearRampToValueAtTime(0.0001, t + 7.4);
250:       o.connect(f); f.connect(g); g.connect(this.musicGain);
251:       o.start(t); o.stop(t + 7.6);
252:     });
253:   }
