15: 
16: export function buildTileLayer(room) {
17:   const { canvas, ctx } = makeCanvas(COLS * TILE, ROWS * TILE);
18:   const th = themeOf(room);
19:   const rnd = mulberry32(room.id.charCodeAt(0) * 9173 + 11);
20: 
21:   const solid = (x, y) => {
22:     if (x < 0 || x >= COLS || y < 0 || y >= ROWS) return true;
23:     return room.grid[y][x] === '#';
24:   };
25: 
26:   for (let y = 0; y < ROWS; y++) {
27:     for (let x = 0; x < COLS; x++) {
28:       const ch = room.grid[y][x];
29:       const X = x * TILE, Y = y * TILE;
30:       if (ch === '#') {
31:         const above = !solid(x, y - 1);
32:         const below = !solid(x, y + 1);
33:         const left = !solid(x - 1, y);
34:         const right = !solid(x + 1, y);
35:         const v = rnd();
36:         // base
37:         px(ctx, X, Y, TILE, TILE, v > .55 ? th.wall2 : th.wall);
38:         // brick courses (8px)
39:         for (let by = 0; by < 2; by++) {
40:           const oy = Y + by * 8;
41:           const offset = (y * 2 + by) % 2 ? 0 : 4;
42:           px(ctx, X, oy, TILE, 1, th.mortar);
43:           px(ctx, X + ((offset + 8) % 16), oy, 1, 8, th.mortar);
44:           px(ctx, X + offset, oy, 1, 8, th.mortar);
45:         }
46:         // block variation
47:         if (v > .72) px(ctx, X + 2 + Math.floor(rnd() * 8), Y + 2 + Math.floor(rnd() * 10), 3, 1, th.wall3);
48:         if (v > .84) px(ctx, X + 1 + Math.floor(rnd() * 10), Y + 3 + Math.floor(rnd() * 8), 1, 3, th.mortar);
49:         // exposed top edge
50:         if (above) {
51:           px(ctx, X, Y, TILE, 2, th.hi);
52:           px(ctx, X, Y + 2, TILE, 1, th.wall3);
53:           for (let i = 0; i < 4; i++) {
54:             if (rnd() > .55) px(ctx, X + Math.floor(rnd() * 14), Y + 2, 2, 1, th.mortar);
55:           }
56:           // moss drips
57:           if (rnd() > .45) {
58:             const mx = X + Math.floor(rnd() * 12);
59:             px(ctx, mx, Y + 2, 1, 2 + Math.floor(rnd() * 4), th.moss);
60:           }
61:         }
62:         if (below) {
63:           px(ctx, X, Y + TILE - 2, TILE, 2, th.deep);
64:           px(ctx, X, Y + TILE - 3, TILE, 1, th.wall3);
65:         }
66:         if (left) {
67:           px(ctx, X, Y, 2, TILE, th.wall3);
68:           px(ctx, X, Y, 1, TILE, th.deep);
69:         }
70:         if (right) {
71:           px(ctx, X + TILE - 2, Y, 2, TILE, th.wall3);
72:           px(ctx, X + TILE - 1, Y, 1, TILE, th.deep);
73:         }
74:         // occasional cracks / bone
75:         if (v > .93) {
76:           px(ctx, X + 6, Y + 4, 1, 5, th.mortar);
77:           px(ctx, X + 7, Y + 8, 2, 1, th.mortar);
78:         }
79:         if (v < .06 && room.theme !== 'roof') {
80:           px(ctx, X + 5, Y + 9, 4, 1, P.bone2);
81:           px(ctx, X + 7, Y + 8, 1, 3, P.bone2);
82:         }
83:       } else if (ch === '=') {
84:         // one-way stone ledge
85:         px(ctx, X, Y, TILE, 2, th.hi);
86:         px(ctx, X, Y + 2, TILE, 5, th.wall2);
87:         px(ctx, X, Y + 7, TILE, 2, th.mortar);
88:         px(ctx, X + 2, Y + 2, 1, 5, th.wall3);
89:         px(ctx, X + 11, Y + 2, 1, 5, th.wall3);
90:         // little supports / carving
91:         px(ctx, X + 5, Y + 3, 2, 2, th.deep);
92:         px(ctx, X + 9, Y + 3, 2, 2, th.deep);
93:         if (rnd() > .5) px(ctx, X + 1 + Math.floor(rnd() * 12), Y + 1, 2, 1, P.bone2);
94:         // hanging moss
95:         if (rnd() > .55) px(ctx, X + Math.floor(rnd() * 14), Y + 8, 1, 2 + Math.floor(rnd() * 3), th.moss);
96:       } else if (ch === '^') {
97:         // spikes
98:         px(ctx, X, Y + 10, TILE, 6, th.deep);
99:         for (let i = 0; i < 4; i++) {
100:           const sx = X + i * 4;
101:           ctx.fillStyle = P.steel2;
102:           ctx.beginPath();
103:           ctx.moveTo(sx, Y + 15);
104:           ctx.lineTo(sx + 2, Y + 4);
105:           ctx.lineTo(sx + 4, Y + 15);
106:           ctx.closePath(); ctx.fill();
107:           px(ctx, sx + 2, Y + 5, 1, 5, P.steel);
108:         }
109:         px(ctx, X, Y + 14, TILE, 2, '#3a3346');
110:       }
111:     }
112:   }
113: 
114:   // door frame trim around openings
115:   for (const d of room.doors) {
116:     ctx.fillStyle = th.hi;
117:     if (d.side === 'left') {
118:       const y0 = d.rows[0] * TILE, y1 = (d.rows[d.rows.length - 1] + 1) * TILE;
119:       px(ctx, 0, y0 - 3, 2, y1 - y0 + 6, th.wall3);
120:     } else if (d.side === 'right') {
121:       const y0 = d.rows[0] * TILE, y1 = (d.rows[d.rows.length - 1] + 1) * TILE;
122:       px(ctx, COLS * TILE - 2, y0 - 3, 2, y1 - y0 + 6, th.wall3);
123:     }
124:   }
125: 
126:   return canvas;
127: }
