132: function pointedArch(ctx, x, y, w, h) {
133:   ctx.beginPath();
134:   ctx.moveTo(x, y + h);
135:   ctx.lineTo(x, y + h * .34);
136:   ctx.quadraticCurveTo(x, y + h * .1, x + w * .5, y);
137:   ctx.quadraticCurveTo(x + w, y + h * .1, x + w, y + h * .34);
138:   ctx.lineTo(x + w, y + h);
139:   ctx.closePath();
140: }
