258: function drawSlash(ctx, x, y, facing, p, seed) {
259:   ctx.save();
260:   ctx.translate(Math.round(x), Math.round(y) - 14);
261:   ctx.scale(facing, 1);
262:   const a0 = -1.9 + p * 2.9;
263:   const r = 17 + Math.sin(p * Math.PI) * 6;
264:   ctx.globalAlpha = 0.28 + Math.sin(p * Math.PI) * 0.5;
265:   ctx.strokeStyle = '#ffd9e4';
266:   ctx.lineWidth = 2;
267:   ctx.beginPath();
268:   ctx.arc(2, 1, r, a0 - 0.9, a0 + 0.55);
269:   ctx.stroke();
270:   ctx.globalAlpha = 0.9;
271:   ctx.strokeStyle = '#ff8fb0';
272:   ctx.lineWidth = 1;
273:   ctx.beginPath();
274:   ctx.arc(2, 1, r - 2, a0 - 0.7, a0 + 0.35);
275:   ctx.stroke();
276:   // blade
277:   const hx = 7, hy = -3;
278:   const bx = hx + Math.cos(a0) * 13, by = hy + Math.sin(a0) * 13;
279:   ctx.strokeStyle = P.steel;
280:   ctx.lineWidth = 1.6;
281:   ctx.beginPath();
282:   ctx.moveTo(hx, hy);
283:   ctx.lineTo(bx, by);
284:   ctx.stroke();
285:   ctx.strokeStyle = '#fff';
286:   ctx.lineWidth = .6;
287:   ctx.beginPath();
288:   ctx.moveTo(hx + 2, hy - .5);
289:   ctx.lineTo(bx, by);
290:   ctx.stroke();
291:   // guard
292:   ctx.fillStyle = P.gold;
293:   ctx.fillRect(hx - 1, hy - 1, 3, 2);
294:   // sparkles
295:   for (let i = 0; i < 3; i++) {
296:     const aa = a0 + (i - 1) * .5;
297:     ctx.fillStyle = i === 1 ? '#fff' : '#ff9dba';
298:     ctx.fillRect(2 + Math.cos(aa) * (r + 2), 1 + Math.sin(aa) * (r + 2), 1, 1);
299:   }
300:   ctx.restore();
301: }
