311:   ctx.save();
312:   if (f < 0) { ctx.translate(x, y); ctx.scale(-1, 1); ctx.translate(-x, -y); }
313: 
314:   if (e.type === 'bat') {
315:     const flap = Math.sin(t * .3 + e.seed) * 4;
316:     const col = c || '#2a2030';
317:     const wing = c || '#3b2b44';
318:     ellipse(ctx, x, y - 5, 3, 3, col);
319:     px(ctx, x - 1, y - 7, 1, 1, c || '#ff5b78');
320:     px(ctx, x + 1, y - 7, 1, 1, c || '#ff5b78');
321:     // wings
322:     ctx.fillStyle = wing;
323:     ctx.beginPath();
324:     ctx.moveTo(x - 2, y - 6);
325:     ctx.lineTo(x - 10, y - 9 - flap);
326:     ctx.lineTo(x - 7, y - 3);
327:     ctx.lineTo(x - 11, y - 1 + flap);
328:     ctx.lineTo(x - 3, y - 2);
329:     ctx.closePath(); ctx.fill();
330:     ctx.beginPath();
331:     ctx.moveTo(x + 2, y - 6);
332:     ctx.lineTo(x + 10, y - 9 + flap);
333:     ctx.lineTo(x + 7, y - 3);
334:     ctx.lineTo(x + 11, y - 1 - flap);
335:     ctx.lineTo(x + 3, y - 2);
336:     ctx.closePath(); ctx.fill();
337:     // ears
338:     px(ctx, x - 3, y - 8, 1, 2, col);
339:     px(ctx, x + 2, y - 8, 1, 2, col);
340:     // fangs
341:     px(ctx, x, y - 2, 1, 1, '#fff');
342:   } else if (e.type === 'crawler') {
343:     const step = Math.sin(t * .3 + e.seed) * 1.5;
344:     const col = c || P.bone2;
345:     const dark = c || '#5a4d43';
346:     // legs
347:     for (let i = 0; i < 3; i++) {
348:       const lx = x - 5 + i * 4;
349:       px(ctx, lx, y - 4 + (i % 2), 1, 5, dark);
350:       px(ctx, lx - 2 + (i % 2), y - 1, 3, 1, dark);
351:     }
352:     // body / skull
353:     ellipse(ctx, x, y - 6, 6, 4, col);
354:     px(ctx, x - 3, y - 8, 6, 1, col);
355:     // eyes
356:     px(ctx, x - 3, y - 7, 2, 2, c || '#ff5b78');
357:     px(ctx, x + 1, y - 7, 2, 2, c || '#ff5b78');
358:     // jaw
359:     px(ctx, x - 2, y - 3 + Math.round(step * .3), 5, 1, dark);
360:     px(ctx, x - 1, y - 2, 1, 1, dark);
361:     px(ctx, x + 1, y - 2, 1, 1, dark);
362:   } else if (e.type === 'wraith') {
363:     const fl = Math.sin(t * .06 + e.seed) * 2;
364:     const col = c || '#7fa39e';
365:     // tattered shroud
366:     for (let i = 0; i < 6; i++) {
367:       const w = 3 + i;
368:       px(ctx, x - w + 1, y - 14 + i * 2 + Math.round(fl), w * 2 - 1, 2, i < 2 ? (c || '#b7d4cd') : col);
369:     }
370:     // rags
371:     for (let i = 0; i < 4; i++) px(ctx, x - 4 + i * 3, y - 1 + Math.round(fl) + (i % 2) * 2, 2, 4, col);
372:     // hood / face void
373:     ellipse(ctx, x, y - 15, 4, 5, c || '#d7e8e2');
374:     ellipse(ctx, x, y - 14, 3, 4, c || '#101820');
375:     px(ctx, x - 2, y - 15, 1, 2, c || '#9dffe9');
376:     px(ctx, x + 1, y - 15, 1, 2, c || '#9dffe9');
