378:     px(ctx, x - 6, y - 11 + Math.round(fl), 2, 6, col);
379:     px(ctx, x + 4, y - 11 + Math.round(fl), 2, 6, col);
380:   } else if (e.type === 'knight') {
381:     const step = e.vx ? Math.sin(t * .2 + e.seed) : 0;
382:     const col = c || '#4a4658';
383:     const light = c || '#6f6a82';
