35: export function mulberry32(a) {
36:   return function () {
37:     a |= 0; a = (a + 0x6D2B79F5) | 0;
38:     let t = Math.imul(a ^ (a >>> 15), 1 | a);
39:     t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
40:     return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
41:   };
42: }
