132: function pointedArch(ctx, x, y, w, h) {
133:   ctx.beginPath();
134:   ctx.moveTo(x, y + h);
135:   ctx.lineTo(x, y + h * .34);
136:   ctx.quadraticCurveTo(x, y + h * .1, x + w * .5, y);
137:   ctx.quadraticCurveTo(x + w, y + h * .1, x + w, y + h * .34);
138:   ctx.lineTo(x + w, y + h);
139:   ctx.closePath();
140: }
141: 
142: function roseWindow(ctx, cx, cy, r, t, bright) {
143:   ctx.save();
144:   ctx.globalAlpha = bright;
145:   ctx.fillStyle = '#0b0813';
146:   ctx.beginPath(); ctx.arc(cx, cy, r + 5, 0, Math.PI * 2); ctx.fill();
147:   const cols = ['#5b1f3b', '#3b2a63', '#6b3a2a', '#224a4a', '#5b1f3b', '#463060', '#7a3a4a', '#2c3d5c'];
148:   for (let i = 0; i < 12; i++) {
149:     const a0 = i / 12 * Math.PI * 2;
150:     const a1 = (i + 1) / 12 * Math.PI * 2;
151:     ctx.fillStyle = cols[i % cols.length];
152:     ctx.beginPath();
153:     ctx.moveTo(cx, cy);
154:     ctx.arc(cx, cy, r, a0, a1);
155:     ctx.closePath();
156:     ctx.fill();
157:   }
158:   ctx.fillStyle = '#c98a5a';
159:   ctx.beginPath(); ctx.arc(cx, cy, r * .3, 0, Math.PI * 2); ctx.fill();
160:   ctx.fillStyle = '#e4b978';
161:   ctx.beginPath(); ctx.arc(cx, cy, r * .17, 0, Math.PI * 2); ctx.fill();
162:   // tracery
163:   ctx.strokeStyle = 'rgba(10,6,14,.85)';
164:   ctx.lineWidth = 1.4;
165:   ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI * 2); ctx.stroke();
166:   ctx.beginPath(); ctx.arc(cx, cy, r * .55, 0, Math.PI * 2); ctx.stroke();
167:   for (let i = 0; i < 12; i++) {
168:     const a = i / 12 * Math.PI * 2;
169:     line(ctx, cx + Math.cos(a) * r * .3, cy + Math.sin(a) * r * .3, cx + Math.cos(a) * r, cy + Math.sin(a) * r, 'rgba(10,6,14,.8)', 1);
170:   }
171:   // glow
172:   ctx.globalAlpha = .12;
173:   ctx.fillStyle = '#e4b978';
174:   ctx.beginPath(); ctx.arc(cx, cy, r + 22, 0, Math.PI * 2); ctx.fill();
175:   ctx.restore();
176: }
177: 
178: function moon(ctx, x, y, r) {
179:   ctx.save();
180:   ctx.globalAlpha = .12;
181:   ctx.fillStyle = '#e8e0ef';
182:   ctx.beginPath(); ctx.arc(x, y, r * 2.6, 0, Math.PI * 2); ctx.fill();
183:   ctx.globalAlpha = 1;
184:   ctx.fillStyle = '#ded3e4';
185:   ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2); ctx.fill();
186:   ctx.fillStyle = '#c8bccf';
187:   ctx.beginPath(); ctx.arc(x - r * .3, y - r * .2, r * .18, 0, Math.PI * 2); ctx.fill();
188:   ctx.beginPath(); ctx.arc(x + r * .25, y + r * .3, r * .12, 0, Math.PI * 2); ctx.fill();
189:   ctx.beginPath(); ctx.arc(x + r * .1, y - r * .45, r * .09, 0, Math.PI * 2); ctx.fill();
190:   ctx.restore();
191: }
