193: export function drawBackground(ctx, room, t, playerX = 240) {
194:   const shift = (playerX - 240) * .022;
195:   const W = COLS * TILE, H = ROWS * TILE;
196:   const th = themeOf(room);
197:   const grad = ctx.createLinearGradient(0, 0, 0, H);
198:   if (room.theme === 'roof') {
199:     grad.addColorStop(0, '#0a0916'); grad.addColorStop(.55, '#141126'); grad.addColorStop(1, '#1d1626');
200:   } else if (room.theme === 'ossuary') {
201:     grad.addColorStop(0, '#081012'); grad.addColorStop(.6, '#0f1a1b'); grad.addColorStop(1, '#122021');
202:   } else if (room.theme === 'chapel') {
203:     grad.addColorStop(0, '#150c1d'); grad.addColorStop(.6, '#211327'); grad.addColorStop(1, '#160c1a');
204:   } else {
205:     grad.addColorStop(0, '#0a0711'); grad.addColorStop(.55, '#120c1a'); grad.addColorStop(1, '#171020');
206:   }
207:   ctx.fillStyle = grad;
208:   ctx.fillRect(0, 0, W, H);
209: 
210:   if (room.theme === 'crypt') {
211:     // deep wall courses
212:     ctx.globalAlpha = .5;
213:     for (let y = 26; y < H; y += 13) {
214:       px(ctx, 0, y, W, 1, '#0d0813');
215:       for (let x = ((y / 13) % 2) * 16; x < W; x += 32) px(ctx, x, y, 1, 13, '#0d0813');
216:     }
217:     ctx.globalAlpha = 1;
218:     // side columns
219:     for (let i = -1; i < 5; i++) {
220:       const cx = 30 + i * 112 - shift;
221:       px(ctx, cx, 18, 18, 226, '#1a1224');
222:       px(ctx, cx + 2, 18, 3, 226, '#2a1e36');
223:       px(ctx, cx + 13, 18, 2, 226, '#0e0915');
224:       px(ctx, cx - 3, 12, 24, 7, '#2a1e36');
225:       px(ctx, cx - 3, 19, 24, 2, '#0e0915');
226:       // capital carving
227:       px(ctx, cx + 6, 26, 6, 3, '#3a2b46');
228:     }
229:     // arches with stained glass
230:     for (let i = 0; i < 3; i++) {
231:       const ax = 78 + i * 150 - shift;
232:       pointedArch(ctx, ax, 44, 64, 130);
233:       ctx.fillStyle = '#0b0712'; ctx.fill();
234:       ctx.strokeStyle = '#3a2b46'; ctx.lineWidth = 2; ctx.stroke();
235:       // glass panes
236:       ctx.save();
237:       pointedArch(ctx, ax + 6, 52, 52, 112); ctx.clip();
238:       ctx.fillStyle = '#2c1a3a'; ctx.fillRect(ax + 6, 52, 52, 112);
239:       const paneCols = ['#5d2440', '#3b2a63', '#224a4a', '#6b3a2a'];
240:       for (let p = 0; p < 5; p++) {
241:         ctx.fillStyle = paneCols[(p + i) % paneCols.length];
242:         ctx.globalAlpha = .75;
243:         ctx.fillRect(ax + 8 + (p % 2) * 25, 60 + p * 20, 22, 17);
244:       }
245:       ctx.globalAlpha = .2;
246:       ctx.fillStyle = '#ffd9a0'; ctx.fillRect(ax + 6, 52, 52, 112);
247:       ctx.restore();
248:       ctx.strokeStyle = '#171020'; ctx.lineWidth = 1;
249:       for (let p = 1; p < 5; p++) line(ctx, ax + 6, 60 + p * 20, ax + 58, 60 + p * 20, '#171020', 1);
250:       line(ctx, ax + 32, 52, ax + 32, 164, '#171020', 1);
251:     }
252:     // candles along walls
253:     for (let i = 0; i < 6; i++) {
254:       const cx = 20 + i * 88 - shift * .5;
255:       const cy = 128 + (i % 2) * 36;
256:       px(ctx, cx, cy, 2, 7, '#d8cbb2');
257:       const fl = Math.sin(t * .2 + i) * 1;
258:       ellipse(ctx, cx + 1, cy - 4 + fl, 2, 3, 'rgba(255,170,90,.18)');
259:       ellipse(ctx, cx + 1, cy - 4 + fl, 1, 2, '#ffce8c');
260:     }
261:     // fog
262:     ctx.globalAlpha = .05;
263:     for (let i = 0; i < 3; i++) {
264:       const fy = 190 + i * 24;
265:       ctx.fillStyle = P.fog;
266:       ctx.beginPath();
267:       ctx.ellipse((W * .5 + Math.sin(t * .008 + i) * 60) - shift, fy, 200, 14, 0, 0, Math.PI * 2);
268:       ctx.fill();
269:     }
270:     ctx.globalAlpha = 1;
271:   } else if (room.theme === 'cloister') {
272:     // arcade
273:     for (let i = 0; i < 5; i++) {
274:       const ax = 18 + i * 108 - shift;
275:       pointedArch(ctx, ax, 54, 60, 170);
276:       ctx.fillStyle = '#0d0814'; ctx.fill();
277:       ctx.strokeStyle = '#33263f'; ctx.lineWidth = 2; ctx.stroke();
278:       pointedArch(ctx, ax + 8, 64, 44, 150);
279:       ctx.fillStyle = '#151020'; ctx.fill();
280:       px(ctx, ax - 4, 40, 68, 6, '#2a2036');
281:       px(ctx, ax - 4, 46, 68, 2, '#0b0710');
282:       // hanging banner
283:       if (i % 2 === 0) {
284:         px(ctx, ax + 24, 46, 12, 48, '#4c1830');
285:         px(ctx, ax + 24, 46, 12, 2, '#7a2a48');
286:         ctx.fillStyle = '#4c1830';
287:         ctx.beginPath();
288:         ctx.moveTo(ax + 24, 94); ctx.lineTo(ax + 36, 94); ctx.lineTo(ax + 30, 104);
289:         ctx.closePath(); ctx.fill();
290:         px(ctx, ax + 29, 62, 2, 12, '#c9a45e');
291:       }
292:     }
293:     // moonlight shafts
294:     ctx.globalAlpha = .035;
295:     ctx.fillStyle = '#cfd8ff';
296:     for (let i = 0; i < 3; i++) {
297:       ctx.beginPath();
298:       ctx.moveTo(40 + i * 160 - shift, 0);
299:       ctx.lineTo(110 + i * 160 - shift, 0);
300:       ctx.lineTo(190 + i * 160 - shift, 272);
301:       ctx.lineTo(80 + i * 160 - shift, 272);
302:       ctx.closePath(); ctx.fill();
303:     }
304:     ctx.globalAlpha = 1;
305:     // floor mist
306:     ctx.globalAlpha = .06;
307:     ctx.fillStyle = '#b7a6c9';
308:     ctx.beginPath(); ctx.ellipse(240 - shift, 238, 250, 20, 0, 0, Math.PI * 2); ctx.fill();
309:     ctx.globalAlpha = 1;
310:   } else if (room.theme === 'ossuary') {
311:     // brick tunnel
312:     ctx.globalAlpha = .5;
313:     for (let y = 8; y < H; y += 11) {
314:       px(ctx, 0, y, W, 1, '#071011');
315:       for (let x = ((y / 11) % 2) * 14; x < W; x += 28) px(ctx, x, y, 1, 11, '#071011');
316:     }
317:     ctx.globalAlpha = 1;
318:     // arched recesses with skulls
319:     for (let i = 0; i < 4; i++) {
320:       const ax = 40 + i * 118 - shift;
321:       pointedArch(ctx, ax, 46, 58, 100);
322:       ctx.fillStyle = '#0a1415'; ctx.fill();
323:       ctx.strokeStyle = '#2c4040'; ctx.lineWidth = 1.5; ctx.stroke();
324:       // stacked bones
325:       for (let b = 0; b < 9; b++) {
326:         const bx = ax + 8 + (b % 3) * 15;
327:         const by = 128 - Math.floor(b / 3) * 9;
328:         px(ctx, bx, by, 10, 2, '#6d6a5a');
329:         px(ctx, bx + 2, by - 1, 6, 1, '#8e8270');
330:       }
331:       // skull
332:       px(ctx, ax + 21, 66, 10, 9, '#b9ae97');
333:       px(ctx, ax + 23, 69, 2, 2, '#1a1a16');
334:       px(ctx, ax + 28, 69, 2, 2, '#1a1a16');
335:       px(ctx, ax + 25, 73, 3, 1, '#1a1a16');
336:     }
337:     // water at the bottom
338:     ctx.globalAlpha = .5;
339:     ctx.fillStyle = '#122b30';
340:     ctx.fillRect(0, 246, W, 26);
341:     for (let i = 0; i < 14; i++) {
342:       const wx = (i * 37 + t * .2) % W;
343:       px(ctx, wx, 248 + (i % 4) * 4, 8 + (i % 3) * 5, 1, 'rgba(120,190,190,.22)');
344:     }
345:     ctx.globalAlpha = 1;
346:     // drips
347:     for (let i = 0; i < 6; i++) {
348:       const dx = 30 + i * 76;
349:       const dy = (t * .6 + i * 41) % 210;
350:       px(ctx, dx, 20 + dy, 1, 3, 'rgba(150,210,205,.25)');
351:     }
352:     ctx.globalAlpha = .06;
353:     ctx.fillStyle = '#8fd8cf';
354:     ctx.beginPath(); ctx.ellipse(240, 120, 230, 120, 0, 0, Math.PI * 2); ctx.fill();
355:     ctx.globalAlpha = 1;
356:   } else if (room.theme === 'tower') {
357:     // huge window
358:     pointedArch(ctx, 166 - shift * .5, 26, 150, 200);
359:     ctx.fillStyle = '#090812'; ctx.fill();
360:     ctx.strokeStyle = '#3a3554'; ctx.lineWidth = 3; ctx.stroke();
361:     ctx.save();
362:     pointedArch(ctx, 174 - shift * .5, 34, 134, 184); ctx.clip();
363:     const sky = ctx.createLinearGradient(0, 30, 0, 210);
364:     sky.addColorStop(0, '#161a35'); sky.addColorStop(.6, '#20223f'); sky.addColorStop(1, '#2b2438');
365:     ctx.fillStyle = sky; ctx.fillRect(160, 30, 170, 190);
366:     moon(ctx, 250 - shift * .5, 78, 20);
367:     // clouds
368:     ctx.globalAlpha = .18;
369:     ctx.fillStyle = '#9d94b8';
370:     for (let i = 0; i < 4; i++) {
371:       const cx = ((i * 97 + t * .06) % 300) + 120 - shift * .5;
372:       ctx.beginPath(); ctx.ellipse(cx, 104 + i * 26, 50, 7, 0, 0, Math.PI * 2); ctx.fill();
373:     }
374:     ctx.globalAlpha = 1;
375:     ctx.restore();
376:     // window tracery
377:     ctx.strokeStyle = '#2b2740'; ctx.lineWidth = 2;
378:     line(ctx, 240 - shift * .5, 34, 240 - shift * .5, 218, '#2b2740', 2);
379:     line(ctx, 176 - shift * .5, 150, 306 - shift * .5, 150, '#2b2740', 2);
380:     // beams / rafters
381:     for (let i = 0; i < 4; i++) {
382:       ctx.save();
383:       ctx.translate(20 + i * 130 - shift, 0);
384:       ctx.rotate(-.5);
385:       px(ctx, 0, 0, 9, 120, '#1d1829');
386:       px(ctx, 0, 0, 3, 120, '#2e2740');
387:       ctx.restore();
388:     }
389:     // bell silhouette
390:     ctx.fillStyle = '#171222';
391:     ctx.beginPath();
392:     ctx.moveTo(76 - shift, 96);
393:     ctx.quadraticCurveTo(92 - shift, 86, 104 - shift, 96);
394:     ctx.lineTo(108 - shift, 132);
395:     ctx.quadraticCurveTo(90 - shift, 144, 72 - shift, 132);
396:     ctx.closePath(); ctx.fill();
397:     px(ctx, 88 - shift, 78, 4, 10, '#171222');
398:     px(ctx, 70 - shift, 132, 40, 3, '#171222');
399:     // hanging chains
400:     for (let i = 0; i < 8; i++) {
401:       px(ctx, 116 + i * 34 - shift, 0, 1, 30 + (i % 3) * 20, 'rgba(140,130,160,.18)');
402:       px(ctx, 115 + i * 34 - shift, 20 + (i % 3) * 20, 3, 2, 'rgba(140,130,160,.12)');
403:     }
404:     // dust motes
405:     for (let i = 0; i < 18; i++) {
406:       const mx = (i * 71 + Math.sin(t * .02 + i) * 14) % W;
407:       const my = (i * 37 + t * .08) % H;
408:       px(ctx, mx, my, 1, 1, 'rgba(230,220,245,.14)');
409:     }
410:   } else if (room.theme === 'roof') {
411:     // stars
412:     for (let i = 0; i < 40; i++) {
413:       const sx = (i * 97) % W, sy = (i * 53) % 180;
414:       ctx.globalAlpha = .2 + (Math.sin(t * .02 + i) + 1) * .15;
415:       px(ctx, sx, sy, 1, 1, i % 7 ? '#cfd4e8' : '#ffd9a0');
416:     }
417:     ctx.globalAlpha = 1;
418:     moon(ctx, 372 - shift * .4, 58, 24);
419:     // clouds
420:     for (let i = 0; i < 5; i++) {
421:       const cx = ((i * 121 + t * .04) % (W + 160)) - 80 - shift * .3;
422:       ctx.globalAlpha = .08;
423:       ctx.fillStyle = '#8f8aa8';
424:       ctx.beginPath(); ctx.ellipse(cx, 48 + i * 22, 90, 10, 0, 0, Math.PI * 2); ctx.fill();
425:     }
426:     ctx.globalAlpha = 1;
427:     // distant cathedral spires
428:     ctx.fillStyle = '#0d0b16';
429:     for (let i = 0; i < 7; i++) {
430:       const bx = i * 80 - 20 - shift * .6;
431:       const bh = 60 + (i * 37) % 70;
432:       px(ctx, bx, 230 - bh, 44, bh + 40, '#0d0b16');
433:       ctx.beginPath();
434:       ctx.moveTo(bx - 4, 230 - bh); ctx.lineTo(bx + 22, 230 - bh - 40); ctx.lineTo(bx + 48, 230 - bh);
435:       ctx.closePath(); ctx.fill();
436:       // lit window
437:       ctx.globalAlpha = .35 + Math.sin(t * .03 + i) * .1;
438:       px(ctx, bx + 18, 230 - bh + 24, 3, 5, '#e4b978');
439:       ctx.globalAlpha = 1;
440:     }
441:     // foreground roof edge
442:     px(ctx, 0, 258, W, 14, '#15121e');
443:     px(ctx, 0, 258, W, 2, '#2c2739');
444:     for (let i = 0; i < 20; i++) px(ctx, i * 25 + 4, 264, 10, 8, '#0e0b15');
445:     // rain
446:     ctx.strokeStyle = 'rgba(180,195,225,.16)';
447:     ctx.lineWidth = 1;
448:     for (let i = 0; i < 46; i++) {
449:       const rx = (i * 41 + t * 1.9) % (W + 40) - 20;
450:       const ry = (i * 67 + t * 6.2) % (H + 40) - 20;
451:       ctx.beginPath(); ctx.moveTo(rx, ry); ctx.lineTo(rx - 2, ry + 7); ctx.stroke();
452:     }
453:   } else if (room.theme === 'chapel') {
454:     // rose window
455:     roseWindow(ctx, 240 - shift * .4, 82, 52, t, .85);
456:     // side lancet windows
457:     for (let i = 0; i < 2; i++) {
458:       const ax = i === 0 ? 70 : 344;
459:       pointedArch(ctx, ax - shift * .5, 52, 56, 140);
460:       ctx.fillStyle = '#120a1a'; ctx.fill();
461:       ctx.strokeStyle = '#4a3455'; ctx.lineWidth = 2; ctx.stroke();
462:       pointedArch(ctx, ax + 7 - shift * .5, 62, 42, 124);
463:       ctx.fillStyle = i ? '#2e1b3e' : '#3a1a34'; ctx.fill();
464:       ctx.globalAlpha = .5;
465:       px(ctx, ax + 14 - shift * .5, 88, 6, 20, '#7a2a48');
466:       px(ctx, ax + 28 - shift * .5, 112, 6, 26, '#3b2a63');
467:       ctx.globalAlpha = 1;
468:     }
469:     // altar silhouette
470:     px(ctx, 196, 188, 88, 34, '#1b1020');
471:     px(ctx, 202, 178, 76, 10, '#241428');
472:     px(ctx, 238, 150, 4, 40, '#2b1830');
473:     px(ctx, 228, 156, 24, 3, '#2b1830');
474:     // pews
475:     for (let i = 0; i < 3; i++) {
476:       px(ctx, 30, 220 + i * 16, 120, 5, '#1b1222');
477:       px(ctx, 330, 220 + i * 16, 120, 5, '#1b1222');
478:     }
479:     // candles / glow
