96:     ctx.rotate(-1.35);
97:     ctx.translate(-6, -2);
98:   }
99: 
100:   const sway = Math.sin(t * 0.06) * 1.2;
101:   const skin = flick ? '#ffffff' : P.skin;
102:   const skin2 = flick ? '#ffd8e0' : P.skin2;
103:   const hair = flick ? '#ff9ab4' : P.hair;
104:   const hair2 = flick ? '#ffd0dd' : P.hair2;
105:   const dress = flick ? '#ffb2c4' : P.dress;
106:   const dress2 = flick ? '#ffe0e8' : P.dress2;
107:   const lace = flick ? '#ffffff' : P.lace;
108:   const crimson = flick ? '#ffffff' : P.crimson;
109: 
110:   // ---- trailing hair / cape (behind body) ----
111:   const trail = state === 'run' ? -3 : dash ? -6 : air ? -2 : 0;
112:   const lift = state === 'fall' ? 3 : state === 'jump' ? -1 : 0;
113:   ellipse(ctx, -4 + trail + sway * .4, -19 + lift, 5, 7, hair);
114:   ellipse(ctx, -7 + trail + sway * .5, -13 + lift, 4, 8, hair);
115:   // cape
116:   ellipse(ctx, -3 + trail * .7, -11 + lift, 5, 8, dress2);
117:   ellipse(ctx, -6 + trail * .8 + sway * .3, -6 + lift, 3.5, 6, P.dress);
118:   // ragged cape hem
119:   for (let i = 0; i < 4; i++) {
120:     px(ctx, -9 + trail * .7 + i * 3 + Math.sin(t * .08 + i) * 1.2, -2 + lift - (i % 2) * 2, 2, 4, dress);
121:   }
122: 
123:   // ---- legs ----
124:   let lfx = -1, lfy = -3, rfx = 2, rfy = -3;
125:   if (state === 'run') {
126:     lfx = -2 + run * 3; lfy = -3 - Math.max(0, run2) * 2;
127:     rfx = 1 - run * 3; rfy = -3 - Math.max(0, -run2) * 2;
128:   } else if (state === 'jump') {
129:     lfx = -1; lfy = -5; rfx = 3; rfy = -2;
130:   } else if (state === 'fall') {
131:     lfx = -2; lfy = -2; rfx = 3; rfy = -4;
132:   } else if (dash) {
133:     lfx = -4; lfy = -4; rfx = 2; rfy = -4;
134:   } else if (state === 'attack') {
135:     lfx = -2; lfy = -3; rfx = 3; rfy = -3;
136:   }
137:   // thighs / stockings
138:   px(ctx, 0 + lfx, -9 + lfy, 3, 5, P.ink);
139:   px(ctx, 0 + rfx, -9 + rfy, 3, 5, P.ink);
140:   // boots
141:   px(ctx, -1 + lfx, -5 + lfy, 5, 3, P.ink);
142:   px(ctx, -1 + rfx, -5 + rfy, 5, 3, P.ink);
143:   px(ctx, -1 + lfx, -5 + lfy, 4, 1, P.hair2);
144:   px(ctx, -1 + rfx, -5 + rfy, 4, 1, P.hair2);
145:   // boot heels
146:   px(ctx, 3 + lfx, -2 + lfy, 2, 1, P.ink);
147:   px(ctx, 3 + rfx, -2 + rfy, 2, 1, P.ink);
148: 
149:   // ---- skirt ----
150:   const skirtSway = state === 'run' ? run * 1.5 : Math.sin(t * .07) * .7;
151:   for (let i = 0; i < 8; i++) {
152:     const w = 3 + Math.round(i * .9);
153:     const off = Math.round(skirtSway * (i / 7));
154:     px(ctx, -w + 2 + off, -11 + i, w * 2 - 2, 1, i > 5 ? dress : dress2);
155:   }
156:   // ragged hem
157:   for (let i = 0; i < 5; i++) {
158:     px(ctx, -4 + i * 2 + Math.round(skirtSway), -3 + (i % 2), 1, 3, dress);
159:   }
160:   // lace trim
161:   for (let i = 0; i < 5; i++) px(ctx, -4 + i * 2, -10 + Math.round(Math.abs(i - 2) * .3), 1, 1, lace);
162:   // corset ribbon
163:   px(ctx, 0, -14, 3, 1, crimson);
164:   px(ctx, 1, -13, 1, 2, crimson);
165:   px(ctx, -1, -15, 1, 1, lace);
166: 
167:   // ---- torso ----
168:   px(ctx, -3, -19, 7, 8, dress2);
169:   px(ctx, -4, -17, 1, 5, dress);
170:   px(ctx, 4, -17, 1, 5, dress);
171:   // bodice trim
172:   px(ctx, -3, -18, 7, 1, P.dress);
173:   px(ctx, -2, -12, 5, 1, lace);
174:   // shoulder ruffles
175:   px(ctx, -5, -19, 2, 2, lace);
176:   px(ctx, 4, -19, 2, 2, lace);
177:   px(ctx, -5, -18, 1, 1, P.dress2);
178:   px(ctx, 5, -18, 1, 1, P.dress2);
179: 
180:   // ---- arms ----
181:   const armSwing = state === 'run' ? run * 2 : 0;
182:   if (state === 'attack') {
183:     // sword arm extended
184:     px(ctx, 3, -18, 6, 2, skin);
185:     px(ctx, 8, -18, 2, 2, skin2);
186:     // rear arm
187:     px(ctx, -5, -17 - armSwing * .3, 2, 6, skin2);
188:   } else if (dash) {
189:     px(ctx, -5, -18, 5, 2, skin2);
190:     px(ctx, 3, -17, 4, 2, skin);
191:   } else {
192:     px(ctx, -5, -18 + armSwing, 2, 7, skin2);
193:     px(ctx, 4, -18 - armSwing, 2, 7, skin);
194:     // hands
195:     px(ctx, -5, -11 + armSwing, 2, 2, skin2);
196:     px(ctx, 4, -11 - armSwing, 2, 2, skin);
197:   }
198: 
199:   // ---- head ----
200:   const hb = bob;
201:   // neck
202:   px(ctx, 0, -21 + hb, 2, 2, skin2);
203:   // face
204:   px(ctx, -3, -26 + hb, 7, 6, skin);
205:   px(ctx, -2, -27 + hb, 5, 1, skin);
206:   px(ctx, 4, -25 + hb, 1, 3, skin2);
207:   px(ctx, -4, -25 + hb, 1, 3, skin2);
208:   // jaw
209:   px(ctx, -2, -20 + hb, 4, 1, skin2);
210:   // eyes (glowing crimson)
211:   px(ctx, 1, -24 + hb, 2, 1, '#ff5b78');
212:   px(ctx, 1, -23 + hb, 1, 1, '#ff8fa5');
213:   px(ctx, -2, -24 + hb, 1, 1, '#b63a58');
214:   // blush
215:   px(ctx, 2, -22 + hb, 1, 1, '#d98b9c');
216:   // mouth
217:   px(ctx, 0, -21 + hb, 1, 1, '#8f3a50');
218: 
219:   // ---- hair ----
220:   // crown
221:   px(ctx, -5, -28 + hb, 9, 3, hair);
222:   px(ctx, -4, -29 + hb, 6, 1, hair);
223:   px(ctx, -6, -26 + hb, 2, 4, hair);
224:   px(ctx, 4, -26 + hb, 2, 4, hair);
225:   // bangs
226:   px(ctx, -4, -26 + hb, 3, 3, hair);
227:   px(ctx, 1, -26 + hb, 4, 2, hair);
228:   px(ctx, 2, -27 + hb, 3, 1, hair2);
229:   px(ctx, -5, -27 + hb, 4, 1, hair2);
230:   px(ctx, -4, -25 + hb, 1, 1, hair2);
231:   // side locks
232:   px(ctx, -6, -25 + hb, 2, 9, hair);
233:   px(ctx, 5, -25 + hb, 2, 7, hair);
234:   px(ctx, -7, -22 + hb, 1, 5, hair2);
235:   px(ctx, 6, -21 + hb, 1, 4, hair2);
236:   // ribbon
237:   px(ctx, 4, -29 + hb, 3, 2, crimson);
238:   px(ctx, 5, -30 + hb, 1, 1, P.crimson2);
239:   px(ctx, 3, -28 + hb, 1, 1, P.crimson2);
240:   // hair sheen
241:   px(ctx, -3, -27 + hb, 3, 1, hair2);
242: 
243:   // ---- hurt flash / eyes ----
244:   if (hurt) {
245:     ctx.globalCompositeOperation = 'source-atop';
246:     px(ctx, -10, -32, 22, 34, 'rgba(255,120,150,.45)');
247:     ctx.globalCompositeOperation = 'source-over';
248:   }
249: 
250:   ctx.restore();
251: 
252:   // ---- sword + slash trail (not mirrored so arc reads correctly) ----
253:   if (state === 'attack') {
254:     drawSlash(ctx, x, y, facing, attack, opts.slashId || 0);
255:   }
256: }
