304: // Enemies
305: // ---------------------------------------------------------------------------
306: export function drawEnemy(ctx, e, t) {
307:   const x = Math.round(e.x), y = Math.round(e.y);
308:   const hit = e.hitT > 0;
309:   const c = hit ? '#ffffff' : null;
310:   const f = e.facing || 1;
311:   ctx.save();
312:   if (f < 0) { ctx.translate(x, y); ctx.scale(-1, 1); ctx.translate(-x, -y); }
313: 
314:   if (e.type === 'bat') {
315:     const flap = Math.sin(t * .3 + e.seed) * 4;
316:     const col = c || '#2a2030';
317:     const wing = c || '#3b2b44';
318:     ellipse(ctx, x, y - 5, 3, 3, col);
319:     px(ctx, x - 1, y - 7, 1, 1, c || '#ff5b78');
320:     px(ctx, x + 1, y - 7, 1, 1, c || '#ff5b78');
321:     // wings
322:     ctx.fillStyle = wing;
323:     ctx.beginPath();
324:     ctx.moveTo(x - 2, y - 6);
325:     ctx.lineTo(x - 10, y - 9 - flap);
326:     ctx.lineTo(x - 7, y - 3);
327:     ctx.lineTo(x - 11, y - 1 + flap);
328:     ctx.lineTo(x - 3, y - 2);
329:     ctx.closePath(); ctx.fill();
330:     ctx.beginPath();
331:     ctx.moveTo(x + 2, y - 6);
332:     ctx.lineTo(x + 10, y - 9 + flap);
333:     ctx.lineTo(x + 7, y - 3);
334:     ctx.lineTo(x + 11, y - 1 - flap);
335:     ctx.lineTo(x + 3, y - 2);
336:     ctx.closePath(); ctx.fill();
337:     // ears
338:     px(ctx, x - 3, y - 8, 1, 2, col);
339:     px(ctx, x + 2, y - 8, 1, 2, col);
340:     // fangs
341:     px(ctx, x, y - 2, 1, 1, '#fff');
342:   } else if (e.type === 'crawler') {
343:     const step = Math.sin(t * .3 + e.seed) * 1.5;
344:     const col = c || P.bone2;
345:     const dark = c || '#5a4d43';
346:     // legs
347:     for (let i = 0; i < 3; i++) {
348:       const lx = x - 5 + i * 4;
349:       px(ctx, lx, y - 4 + (i % 2), 1, 5, dark);
350:       px(ctx, lx - 2 + (i % 2), y - 1, 3, 1, dark);
351:     }
352:     // body / skull
353:     ellipse(ctx, x, y - 6, 6, 4, col);
354:     px(ctx, x - 3, y - 8, 6, 1, col);
355:     // eyes
356:     px(ctx, x - 3, y - 7, 2, 2, c || '#ff5b78');
357:     px(ctx, x + 1, y - 7, 2, 2, c || '#ff5b78');
358:     // jaw
359:     px(ctx, x - 2, y - 3 + Math.round(step * .3), 5, 1, dark);
360:     px(ctx, x - 1, y - 2, 1, 1, dark);
361:     px(ctx, x + 1, y - 2, 1, 1, dark);
362:   } else if (e.type === 'wraith') {
363:     const fl = Math.sin(t * .06 + e.seed) * 2;
364:     const col = c || '#7fa39e';
365:     // tattered shroud
366:     for (let i = 0; i < 6; i++) {
367:       const w = 3 + i;
368:       px(ctx, x - w + 1, y - 14 + i * 2 + Math.round(fl), w * 2 - 1, 2, i < 2 ? (c || '#b7d4cd') : col);
369:     }
370:     // rags
371:     for (let i = 0; i < 4; i++) px(ctx, x - 4 + i * 3, y - 1 + Math.round(fl) + (i % 2) * 2, 2, 4, col);
372:     // hood / face void
373:     ellipse(ctx, x, y - 15, 4, 5, c || '#d7e8e2');
374:     ellipse(ctx, x, y - 14, 3, 4, c || '#101820');
375:     px(ctx, x - 2, y - 15, 1, 2, c || '#9dffe9');
376:     px(ctx, x + 1, y - 15, 1, 2, c || '#9dffe9');
377:     // arms
378:     px(ctx, x - 6, y - 11 + Math.round(fl), 2, 6, col);
379:     px(ctx, x + 4, y - 11 + Math.round(fl), 2, 6, col);
380:   } else if (e.type === 'knight') {
381:     const step = e.vx ? Math.sin(t * .2 + e.seed) : 0;
382:     const col = c || '#4a4658';
383:     const light = c || '#6f6a82';
384:     // legs
385:     px(ctx, x - 4, y - 7 + step, 3, 7, col);
386:     px(ctx, x + 2, y - 7 - step, 3, 7, col);
387:     // body
388:     px(ctx, x - 5, y - 18, 11, 11, col);
389:     px(ctx, x - 5, y - 18, 11, 2, light);
390:     px(ctx, x - 5, y - 10, 11, 2, c || '#2c2937');
391:     // pauldrons
392:     px(ctx, x - 8, y - 18, 3, 4, light);
393:     px(ctx, x + 6, y - 18, 3, 4, light);
394:     // helmet
395:     px(ctx, x - 4, y - 25, 9, 7, light);
396:     px(ctx, x - 3, y - 24, 7, 4, c || '#2c2937');
397:     px(ctx, x - 2, y - 23, 2, 1, c || '#ff5b78');
398:     px(ctx, x + 1, y - 23, 2, 1, c || '#ff5b78');
399:     px(ctx, x - 1, y - 28, 2, 3, c || P.crimson);
400:     // sword
401:     ctx.strokeStyle = c || P.steel;
402:     ctx.lineWidth = 1;
403:     ctx.beginPath();
404:     ctx.moveTo(x + 8, y - 15);
405:     ctx.lineTo(x + 11, y - 24 + step);
406:     ctx.stroke();
407:     // shield
408:     px(ctx, x - 10, y - 17, 2, 7, c || '#5a5266');
409:   } else if (e.type === 'gargoyle') {
410:     const flap = Math.sin(t * .22 + e.seed) * 5;
411:     const col = c || '#3b3444';
412:     const wing = c || '#4d4258';
413:     ellipse(ctx, x, y - 10, 5, 7, col);
414:     // wings
415:     ctx.fillStyle = wing;
416:     ctx.beginPath();
417:     ctx.moveTo(x - 3, y - 14);
418:     ctx.lineTo(x - 14, y - 17 - flap);
419:     ctx.lineTo(x - 10, y - 8);
420:     ctx.lineTo(x - 15, y - 5 + flap);
421:     ctx.lineTo(x - 3, y - 7);
422:     ctx.closePath(); ctx.fill();
423:     ctx.beginPath();
424:     ctx.moveTo(x + 3, y - 14);
425:     ctx.lineTo(x + 14, y - 17 + flap);
426:     ctx.lineTo(x + 10, y - 8);
427:     ctx.lineTo(x + 15, y - 5 - flap);
428:     ctx.lineTo(x + 3, y - 7);
429:     ctx.closePath(); ctx.fill();
430:     // horns
431:     px(ctx, x - 4, y - 20, 2, 4, col);
432:     px(ctx, x + 2, y - 20, 2, 4, col);
433:     px(ctx, x - 5, y - 21, 1, 2, col);
434:     px(ctx, x + 4, y - 21, 1, 2, col);
435:     // eyes
436:     px(ctx, x - 3, y - 13, 2, 2, c || '#ffd06a');
437:     px(ctx, x + 1, y - 13, 2, 2, c || '#ffd06a');
438:     // claws
439:     px(ctx, x - 3, y - 3, 1, 3, col);
440:     px(ctx, x + 2, y - 3, 1, 3, col);
441:   } else if (e.type === 'orb') {
442:     const r = 4 + Math.sin(t * .2) * 1;
443:     ctx.globalAlpha = .35;
444:     ellipse(ctx, x, y, r + 4, r + 4, c || '#ff5b78');
445:     ctx.globalAlpha = 1;
446:     ellipse(ctx, x, y, r, r, c || '#ffd0dd');
447:     ellipse(ctx, x - 1, y - 1, 1.5, 1.5, '#fff');
448:   }
449:   ctx.restore();
450: }
