455: export function drawItem(ctx, it, t) {
456:   const x = Math.round(it.x), y = Math.round(it.y);
457:   const bob = Math.sin(t * .08 + (it.seed || 0)) * 2;
458:   const pulse = .55 + Math.sin(t * .11 + (it.seed || 0)) * .2;
459:   ctx.save();
460:   ctx.globalAlpha = pulse;
461:   const col = it.type === 'dash' ? '#a88bff' : it.type === 'heart' ? '#ff7d9d' : '#8fd8ff';
462:   ellipse(ctx, x, y - 10 + bob, 14, 14, col);
463:   ctx.globalAlpha = 1;
464:   ctx.globalAlpha = .28;
465:   ellipse(ctx, x, y - 10 + bob, 9, 9, '#fff');
466:   ctx.globalAlpha = 1;
467: 
468:   if (it.type === 'doublejump') {
469:     // batwing reliquary
470:     px(ctx, x - 6, y - 16 + bob, 12, 2, '#e8e2ee');
471:     px(ctx, x - 8, y - 14 + bob, 3, 5, '#d8d0e2');
472:     px(ctx, x + 5, y - 14 + bob, 3, 5, '#d8d0e2');
473:     px(ctx, x - 5, y - 14 + bob, 10, 8, '#efe7f4');
474:     px(ctx, x - 3, y - 12 + bob, 6, 4, '#8fd8ff');
475:     px(ctx, x - 1, y - 11 + bob, 2, 2, '#fff');
476:     px(ctx, x - 9, y - 13 + bob, 1, 3, '#9c8fae');
477:     px(ctx, x + 8, y - 13 + bob, 1, 3, '#9c8fae');
478:   } else if (it.type === 'dash') {
479:     // veilstep talisman
480:     ctx.fillStyle = '#efe7f4';
481:     ctx.beginPath();
482:     ctx.moveTo(x, y - 18 + bob);
483:     ctx.lineTo(x + 7, y - 9 + bob);
484:     ctx.lineTo(x, y - 2 + bob);
485:     ctx.lineTo(x - 7, y - 9 + bob);
486:     ctx.closePath(); ctx.fill();
487:     px(ctx, x - 2, y - 13 + bob, 4, 6, '#a88bff');
488:     px(ctx, x - 1, y - 12 + bob, 2, 2, '#fff');
489:     px(ctx, x - 1, y - 5 + bob, 2, 2, '#c9b5ff');
490:   } else {
491:     // heart reliquary
492:     px(ctx, x - 5, y - 15 + bob, 4, 4, '#ff9ab4');
493:     px(ctx, x + 1, y - 15 + bob, 4, 4, '#ff9ab4');
494:     px(ctx, x - 5, y - 12 + bob, 10, 4, '#ff7d9d');
495:     px(ctx, x - 4, y - 9 + bob, 8, 3, '#e05177');
496:     px(ctx, x - 2, y - 6 + bob, 4, 2, '#a92b4d');
497:     px(ctx, x - 3, y - 14 + bob, 2, 2, '#ffe0e8');
498:     px(ctx, x + 2, y - 14 + bob, 1, 1, '#ffe0e8');
499:   }
500:   ctx.restore();
501: }
