503: export function drawShrine(ctx, s, t, active) {
504:   const x = Math.round(s.x), y = Math.round(s.y);
505:   // altar
506:   px(ctx, x - 11, y - 8, 22, 8, P.stone2);
507:   px(ctx, x - 11, y - 8, 22, 1, P.stone3);
508:   px(ctx, x - 9, y - 6, 18, 4, P.stone);
509:   px(ctx, x - 13, y - 1, 26, 1, '#120b18');
510:   px(ctx, x - 12, y - 2, 24, 1, P.stone2);
511:   // statue
512:   px(ctx, x - 3, y - 18, 6, 10, '#3a2a46');
513:   px(ctx, x - 2, y - 22, 5, 5, '#4c3759');
514:   px(ctx, x - 4, y - 20, 2, 7, '#3a2a46');
515:   px(ctx, x + 3, y - 20, 2, 7, '#3a2a46');
516:   // halo
517:   ctx.strokeStyle = active ? '#ffcf8a' : '#6d5a78';
518:   ctx.lineWidth = 1;
519:   ctx.beginPath(); ctx.arc(x + .5, y - 24, 6, 0, Math.PI * 2); ctx.stroke();
520:   // candle
521:   px(ctx, x - 7, y - 11, 2, 3, '#e8dcc2');
522:   px(ctx, x + 5, y - 11, 2, 3, '#e8dcc2');
523:   const f = Math.sin(t * .25) * 1;
524:   if (active) {
525:     ellipse(ctx, x - 6, y - 14 + f * .3, 2, 3, 'rgba(255,170,90,.35)');
526:     ellipse(ctx, x - 6, y - 14 + f * .3, 1, 2, '#ffd9a0');
527:     ellipse(ctx, x + 6, y - 14 - f * .3, 2, 3, 'rgba(255,170,90,.35)');
528:     ellipse(ctx, x + 6, y - 14 - f * .3, 1, 2, '#ffd9a0');
529:   } else {
530:     px(ctx, x - 6, y - 13, 1, 2, '#5b4c61');
531:     px(ctx, x + 6, y - 13, 1, 2, '#5b4c61');
