8: const WALL = '#';
9: 
10: function blankGrid() {
11:   const g = [];
12:   for (let y = 0; y < ROWS; y++) {
13:     g.push(new Array(COLS).fill('.'));
14:   }
15:   // outer shell
16:   for (let x = 0; x < COLS; x++) { g[0][x] = WALL; g[ROWS - 1][x] = WALL; }
17:   for (let y = 0; y < ROWS; y++) { g[y][0] = WALL; g[y][COLS - 1] = WALL; }
18:   // floor
19:   for (let x = 1; x < COLS - 1; x++) { g[15][x] = WALL; g[16][x] = WALL; }
20:   return g;
21: }
22: 
23: function applyOps(g, ops = []) {
24:   for (const op of ops) {
25:     const [kind, ...a] = op;
26:     if (kind === 'fill') {
27:       const [x, y, w, h, c = WALL] = a;
28:       for (let yy = y; yy < y + h; yy++) for (let xx = x; xx < x + w; xx++) {
29:         if (yy >= 0 && yy < ROWS && xx >= 0 && xx < COLS) g[yy][xx] = c;
30:       }
31:     } else if (kind === 'carve') {
32:       const [x, y, w, h] = a;
33:       for (let yy = y; yy < y + h; yy++) for (let xx = x; xx < x + w; xx++) {
34:         if (yy >= 0 && yy < ROWS && xx >= 0 && xx < COLS) g[yy][xx] = '.';
35:       }
36:     } else if (kind === 'ground') {
37:       const [x, w, row = 15] = a;
38:       for (let xx = x; xx < x + w; xx++) for (let yy = row; yy < ROWS; yy++) {
39:         if (xx >= 0 && xx < COLS) g[yy][xx] = WALL;
40:       }
41:     } else if (kind === 'platform') {
42:       const [x, y, w] = a;
43:       for (let xx = x; xx < x + w; xx++) {
44:         if (xx >= 0 && xx < COLS && y >= 0 && y < ROWS) g[y][xx] = '=';
45:       }
46:     } else if (kind === 'spikes') {
47:       const [x, y, w] = a;
48:       for (let xx = x; xx < x + w; xx++) {
49:         if (xx >= 0 && xx < COLS && y >= 0 && y < ROWS) g[y][xx] = '^';
50:       }
51:     } else if (kind === 'pillar') {
52:       const [x, y, h] = a;
53:       for (let yy = y; yy < y + h; yy++) {
54:         if (yy >= 0 && yy < ROWS) g[yy][x] = WALL;
55:       }
56:     }
57:   }
58:   return g;
59: }
60: 
61: function carveDoors(g, doors = []) {
62:   for (const d of doors) {
63:     if (d.side === 'left') for (const r of d.rows) g[r][0] = '.';
64:     if (d.side === 'right') for (const r of d.rows) g[r][COLS - 1] = '.';
65:     if (d.side === 'top') for (const c of d.cols) g[0][c] = '.';
66:     if (d.side === 'bottom') for (const c of d.cols) { g[ROWS - 1][c] = '.'; g[ROWS - 2][c] = '.'; }
67:   }
68: }
